#include <stdio.h>
#include <string.h>

#define MAXN 20
#define INF 1e18

int N;
long long A[MAXN], B[MAXN];
double dp[1<<MAXN][MAXN];

int main(){
    scanf("%d", &N);
    for(int i = 0; i < N; i++) scanf("%lld %lld", &A[i], &B[i]);

    int full = (1<<N)-1;
    for(int m = 0; m <= full; m++)
        for(int v = 0; v < N; v++)
            dp[m][v] = INF;

    dp[1][0] = 0; // start at vertex 0, mask = {0}

    for(int mask = 1; mask <= full; mask++){
        for(int v = 0; v < N; v++){
            if(!(mask & (1<<v))) continue;
            if(dp[mask][v] >= INF) continue;
            for(int u = 0; u < N; u++){
                if(mask & (1<<u)) continue;
                int nmask = mask | (1<<u);
                long long w = A[v] < B[u] ? A[v] : B[u];
                double nc = dp[mask][v] + w;
                if(nc < dp[nmask][u]) dp[nmask][u] = nc;
            }
        }
    }

    double ans = INF;
    for(int v = 0; v < N; v++){
        if(dp[full][v] >= INF) continue;
        long long w = A[v] < B[0] ? A[v] : B[0];
        double c = dp[full][v] + w;
        if(c < ans) ans = c;
    }

    printf("%lld\n", (long long)ans);
    return 0;
}

