typedef long long ll;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    ll *A = (ll *)malloc((size_t)N * sizeof(ll));
    ll *B = (ll *)malloc((size_t)N * sizeof(ll));
    ll sumA = 0, sumB = 0;

    for (int i = 0; i < N; i++) {
        scanf("%lld %lld", &A[i], &B[i]);
        sumA += A[i];
        sumB += B[i];
    }

    if (N == 1) {
        /* Only cycle is 1 -> 1 */
        ll ans = (A[0] < B[0]) ? A[0] : B[0];
        printf("%lld\n", ans);
        free(A);
        free(B);
        return 0;
    }

    /*
      For any Hamiltonian cycle, each vertex i has exactly one outgoing edge
      contributing min(A_i, B_next), and one incoming edge from prev contributing
      min(A_prev, B_i).

      If all A_i <= B_next for every used edge, total is sum A.
      If all B_i <= A_prev for every used edge, total is sum B.

      These are achievable iff there exists a Hamiltonian cycle avoiding certain
      forbidden successors/predecessors. In a complete digraph, such a cycle exists
      unless all vertices force the same unique successor/predecessor, which happens
      exactly when all minimum-side vertices collapse to one vertex.

      Therefore answer is:
        min(sumA, sumB) unless one side has a unique global minimum and is strictly
        smaller than every value on the other side, in which case we must pay extra.

      More directly:
        Let amin = min A, cntA = count of amin
        Let bmin = min B, cntB = count of bmin

        If sumA <= sumB:
          We want total sumA. This fails only if there is a unique vertex p with
          minimum A and A_p < bmin, because then every vertex must go to p, impossible.
          Best repair is one edge not ending at p, costing at least min B.
          So answer = sumA + (bmin - amin).
        Symmetrically for sumB.
    */

    ll amin = A[0], bmin = B[0];
    int cntA = 0, cntB = 0;

    for (int i = 0; i < N; i++) {
        if (A[i] < amin) amin = A[i];
        if (B[i] < bmin) bmin = B[i];
    }
    for (int i = 0; i < N; i++) {
        if (A[i] == amin) cntA++;
        if (B[i] == bmin) cntB++;
    }

    ll ans;
    if (sumA < sumB) {
        if (cntA == 1 && amin < bmin) ans = sumA + (bmin - amin);
        else ans = sumA;
    } else if (sumB < sumA) {
        if (cntB == 1 && bmin < amin) ans = sumB + (amin - bmin);
        else ans = sumB;
    } else {
        /* sumA == sumB, either side is fine; take the feasible one */
        ll ansA = sumA;
        if (cntA == 1 && amin < bmin) ansA = sumA + (bmin - amin);

        ll ansB = sumB;
        if (cntB == 1 && bmin < amin) ansB = sumB + (amin - bmin);

        ans = (ansA < ansB) ? ansA : ansB;
    }

    printf("%lld\n", ans);

    free(A);
    free(B);
    return 0;
}

