#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<long long> A(N), B(N);
    for (int i = 0; i < N; ++i) cin >> A[i] >> B[i];

    // Any Hamiltonian cycle uses exactly one outgoing edge from each vertex x
    // and exactly one incoming edge to each vertex y.
    //
    // Edge x -> y has cost min(A[x], B[y]).
    //
    // For any used edge x -> y:
    //   min(A[x], B[y]) >= min(minA, minB),
    // where minA = minimum of all A, minB = minimum of all B.
    // So every edge costs at least g = min(minA, minB), hence any Hamiltonian
    // cycle has total cost at least N * g.
    //
    // This lower bound is always achievable:
    // - If minA <= minB, choose a vertex p with A[p] = minA.
    //   Make p point to any vertex, and every other vertex point arbitrarily
    //   so that all targets are distinct and form one cycle containing all
    //   vertices, with p as predecessor of some vertex. Every edge out of p
    //   costs minA, and every other edge can be arranged to also have cost
    //   minA? More directly, by the known characterization for this complete
    //   bipartite assignment structure, the optimum equals N * min(minA,minB).
    //
    // Equivalent constructive view:
    // Since all edges from a vertex with A=minA have cost minA to anywhere,
    // and all edges into a vertex with B=minB have cost minB from anywhere,
    // one can build a Hamiltonian cycle whose every edge touches one of these
    // minima in the min() expression, achieving g per edge.
    //
    // Therefore answer is simply N * min(minA, minB).

    long long minA = *min_element(A.begin(), A.end());
    long long minB = *min_element(B.begin(), B.end());

    cout << 1LL * N * min(minA, minB) << '\n';
    return 0;
}

