import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        long[] A = new long[N];
        long[] B = new long[N];

        long sumMin = 0;
        long minA = Long.MAX_VALUE;
        long minB = Long.MAX_VALUE;

        for (int i = 0; i < N; i++) {
            A[i] = fs.nextLong();
            B[i] = fs.nextLong();
            sumMin += Math.min(A[i], B[i]);
            if (A[i] < minA) minA = A[i];
            if (B[i] < minB) minB = B[i];
        }

        // For any Hamiltonian cycle, total cost is:
        // sum over vertices x of min(A_x, B_{next(x)})
        //
        // Lower bound:
        // min(A_x, B_{next(x)}) >= min(A_x, B_x) unless we "pair" x with some different next vertex.
        //
        // It can be shown the optimum is:
        // - sum min(A_i, B_i), if there exists at least one i with A_i <= B_i
        //   and at least one j with B_j <= A_j (including equality),
        //   because we can arrange a cycle among all vertices without increasing the sum.
        //
        // Otherwise all A_i < B_i, then every edge cost is determined by A_i, so answer = sum A_i.
        // Or all B_i < A_i, then every incoming choice cost is determined by B_next, so answer = sum B_i.
        //
        // These three cases are exactly captured by:
        // answer = max(sum min(A_i, B_i), min(sum A_i, sum B_i))? No.
        //
        // The correct compact criterion:
        // If all A_i < B_i => answer = sum A_i
        // Else if all B_i < A_i => answer = sum B_i
        // Else answer = sum min(A_i, B_i)

        boolean allALessB = true;
        boolean allBLessA = true;
        long sumA = 0, sumB = 0;

        for (int i = 0; i < N; i++) {
            sumA += A[i];
            sumB += B[i];
            if (!(A[i] < B[i])) allALessB = false;
            if (!(B[i] < A[i])) allBLessA = false;
        }

        long ans;
        if (allALessB) ans = sumA;
        else if (allBLessA) ans = sumB;
        else ans = sumMin;

        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}
